parameters.jsCode:
const inputItems = $input.all();
const originalItems = $('Get Pending Feedback').all();

return inputItems.map((item, index) => {
  const aiOutput = item.json.output?.[0]?.content?.[0]?.text;
  const original = originalItems[index]?.json;

  if (!aiOutput) {
    throw new Error('AI analysis output was not found.');
  }

  // The AI node may return the structured result as an object
  // or as a JSON string, so handle both cases.
  const analysis =
    typeof aiOutput === 'string'
      ? JSON.parse(aiOutput)
      : aiOutput;

  return {
    json: {
      feedback_id: original.feedback_id,
      feedback_request_id: original.feedback_request_id,
      customer_id: original.customer_id,
      visit_id: original.visit_id,
      location_id: original.location_id,
      job_reference: original.job_reference,

      sentiment: analysis.sentiment,
      sentiment_score: analysis.sentiment_score,
      severity: analysis.severity,
      severity_score: analysis.severity_score,
      confidence_score: analysis.confidence_score,
      ai_reason: analysis.ai_reason
    }
  };
});

values.content:
=You are an assistant helping an auto-repair and car-care business prepare customer responses.

Generate a professional response draft for INTERNAL HUMAN REVIEW based on the customer's feedback.

Rules:
- Be empathetic and professional.
- Acknowledge the customer's specific concern.
- Do not blame the customer.
- Do not make promises about refunds, discounts, repairs, or compensation.
- Do not claim that the business has already taken action.
- Do not say that the response has been sent.
- Do not mention AI.
- Do not invent facts that are not present in the feedback.
- Keep the response concise and natural.
- The draft will be reviewed by a human before anything is sent.
- Do not use placeholders such as [Your Name], [Company Name], [Position], or similar placeholders.
- End the response naturally without a signature unless a specific business name or staff name is provided in the input.

Customer name:
{{ $('Get Pending Feedback').item.json.full_name }}

Customer feedback:
{{ $('Get Pending Feedback').item.json.comments }}

Overall rating:
{{ $('Get Pending Feedback').item.json.overall_rating }}

Technician rating:
{{ $('Get Pending Feedback').item.json.technician_rating }}

Facility rating:
{{ $('Get Pending Feedback').item.json.facility_rating }}

Waiting time rating:
{{ $('Get Pending Feedback').item.json.waiting_time_rating }}

Feedback category:
{{ $('Get Pending Feedback').item.json.feedback_category }}

