- Acknowledge the positive experience expressed in their comment.
- Personalize the response using their comment where appropriate.
- Do not address the customer by name.
- Do not invent facts or promises.
- Do not mention AI, automation, analysis, sentiment, or internal processes.
- Do not ask the customer to leave another review.
- Keep it concise: 2–4 sentences.
- Return ONLY valid JSON in exactly this format:

{
  "response_draft": "Your response here"
}

parameters.jsCode:
const output = $json.output?.[0]?.content?.[0]?.text;

if (!output) {
  throw new Error('No AI response was returned.');
}

let parsed;

try {
  parsed = JSON.parse(output);
} catch (error) {
  throw new Error(`AI response is not valid JSON: ${output}`);
}

if (!parsed.response_draft) {
  throw new Error('AI response is missing response_draft.');
}

return {
  json: {
    feedback_id: $('Get Pending Feedback').item.json.feedback_id,
    response_draft: parsed.response_draft,
  }
};
